ClientState = {
    init: async function(app, container, client) {
        app = app || session.app;
        container = container || $(".component[name=ClientState]");
        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
        var appId = client.apps.filter(r => r.environment == "")[0].appId;
        var appData = await api.get("ContentManagement/App(" + appId + ")");
        var transactionInstance =(await api.get("DocumentManagement/File?$filter=Folder/AppId eq " + appId + " and startswith(Folder/Path, 'data/transactions/processed') and startswith(Name, 'Report')&$orderby=CreatedOn desc&$top=1")).value[0].Name.substr(7).replace(".json", "");
        var masterdataInstance = (await api.get("DocumentManagement/File?$filter=Folder/AppId eq " + appId + " and startswith(Folder/Path, 'data/masterdata/processed') and startswith(Name, 'Report')&$orderby=CreatedOn desc&$top=1")).value[0].Name.substr(7).replace(".json", "");
        loadComponent($("[name=transactions]"), "TransactionImportResults", async (c) => {
            await api.get("Workflow/FlowInstanceData(" + transactionInstance + ")").then((instanceData) => {
                c.init(appData, $("[name=transactions]"),instanceData);
            });
        });
        loadComponent($("[name=masterdata]"), "MasterdataImportResults", async (c) => {
            await api.get("Workflow/FlowInstanceData(" + masterdataInstance + ")").then((instanceData) => {
                c.init(appData, $("[name=masterdata]"),instanceData);
            });
        });

    }
}
